mapper.select:
SELECT id, admin_username AS adminUsername, operation_type AS operationType,
       description, target_type AS targetType, target_id AS targetId,
       ip_address AS ipAddress, created_at AS createdAt
FROM t_operation_log


        AND operation_type = #{operationType}


        AND created_at >= #{startTime}


        AND created_at <= #{endTime}


ORDER BY created_at DESC
